-- Reviewed official Garmin product facts, captured 2026-09-13.
-- Exact catalog ID AND product URL must match. No IDs, legacy descriptions,
-- installation assignments, permissions or public approvals are modified.
-- Retail SKU links are reviewed against the exact SKU/product specification.
-- Connect IQ/libmtp candidate links remain PENDING. No source snapshots,
-- product images, private reports or complete third-party datasets are shipped.
CREATE TEMP TABLE identity_specification_seed (facts jsonb) ON COMMIT DROP;
UPDATE device_model d SET
 screen_technology=COALESCE(s.facts->>'screen_technology',d.screen_technology),
 solar=COALESCE((s.facts->>'solar')::boolean,d.solar),
 inreach=COALESCE((s.facts->>'inreach')::boolean,d.inreach),
 specification_source=s.facts->>'source', specification_checked_at='2026-09-13T00:00:00Z',
 specification_evidence=d.specification_evidence || (s.facts->'evidence'), updated_at=now()
FROM identity_specification_seed s
WHERE d.id=s.facts->>'id' AND d.product_url=s.facts->>'source';
WITH imported AS (
 SELECT 'RETAIL_SKU',sku.value,d.id,s.facts->>'source',s.facts->>'version','APPROVED',
 'Reviewed official SKU belongs to this exact Garmin product ID and its specifications; no cross-model duplicate in the 2026-09-13 catalog review.',now()
 FROM identity_specification_seed s
 JOIN device_model d ON d.id=s.facts->>'id' AND d.product_url=s.facts->>'source'
 CROSS JOIN LATERAL jsonb_array_elements_text(s.facts->'skus') sku(value)
 WHERE NOT EXISTS (SELECT 1 FROM device_identity_mapping existing
                   WHERE existing.kind='RETAIL_SKU' AND existing.value=sku.value AND existing.device_model_id<>d.id)
 ON CONFLICT DO NOTHING RETURNING id,review_reason
)
SELECT id,'PENDING','APPROVED',review_reason FROM imported;
CREATE TEMP TABLE identity_mapping_seed (facts jsonb) ON COMMIT DROP;
SELECT s.facts->>'kind',s.facts->>'value',d.id,s.facts->>'source_url',s.facts->>'source_version',s.facts->'source_names'
FROM identity_mapping_seed s JOIN device_model d ON d.id=s.facts->>'device_model_id'
ON CONFLICT DO NOTHING;
